1	import React, { useEffect, useState } from 'react';
2	import { ProjectInvoices } from './ProjectInvoices';
3	import { ProjectNotes } from './ProjectNotes';
4	import { ProjectTags } from './ProjectTags';
5	import { ProjectTasks } from './ProjectTasks';
6	
7	// The projects feature owns its own state, data loading and layout (no global store). It lists every
8	// project with its client's NAME (a cross-entity join surfaced in the UI) and adds a new project by
9	// name + chosen client. The client select's option values are client ids.
10	type Project = {
11	  id: number;
12	  name: string;
13	  clientId: number;
14	  clientName: string;
15	  archived: boolean;
16	  status: string;
17	  tagIds: number[];
18	};
19	type Client = { id: number; name: string; email: string };
20	type Tag = { id: number; name: string };
21	
22	// A project is marked active, on hold or finished; the owner picks when creating one.
23	const PROJECT_STATUSES = ['ACTIVE', 'ON_HOLD', 'FINISHED'];
24	
25	export function ProjectsPage() {
26	  const [projects, setProjects] = useState<Project[]>([]);
27	  const [clients, setClients] = useState<Client[]>([]);
28	  const [tags, setTags] = useState<Tag[]>([]);
29	  const [name, setName] = useState('');
30	  const [clientId, setClientId] = useState('');
31	  const [status, setStatus] = useState('ACTIVE');
32	  const [openProjectId, setOpenProjectId] = useState<number | null>(null);
33	  const [showArchived, setShowArchived] = useState(false);
34	  const [filterTagId, setFilterTagId] = useState('');
35	  const [filterStatus, setFilterStatus] = useState('');
36	
37	  async function load() {
38	    const [pRes, cRes, tRes] = await Promise.all([
39	      fetch('/api/projects'),
40	      fetch('/api/clients'),
41	      fetch('/api/tags'),
42	    ]);
43	    setProjects(await pRes.json());
44	    setClients(await cRes.json());
45	    setTags(await tRes.json());
46	  }
47	
48	  useEffect(() => {
49	    void load();
50	  }, []);
51	
52	  async function remove(projectId: number) {
53	    const res = await fetch(`/api/projects/${projectId}`, { method: 'DELETE' });
54	    if (!res.ok) {
55	      return;
56	    }
57	    if (openProjectId === projectId) {
58	      setOpenProjectId(null);
59	    }
60	    await load();
61	  }
62	
63	  // Archiving tucks a project away: it drops off the list unless archived ones are revealed, and is
64	  // retained (the server keeps the row, just flagged). Delete still removes a project outright.
65	  async function archive(projectId: number) {
66	    const res = await fetch(`/api/projects/${projectId}/archive`, { method: 'POST' });
67	    if (!res.ok) {
68	      return;
69	    }
70	    if (openProjectId === projectId) {
71	      setOpenProjectId(null);
72	    }
73	    await load();
74	  }
75	
76	  async function onSubmit(e: React.FormEvent) {
77	    e.preventDefault();
78	    const res = await fetch('/api/projects', {
79	      method: 'POST',
80	      headers: { 'Content-Type': 'application/json' },
81	      body: JSON.stringify({ name, clientId: Number(clientId), status }),
82	    });
83	    if (!res.ok) {
84	      return;
85	    }
86	    setName('');
87	    setClientId('');
88	    setStatus('ACTIVE');
89	    await load();
90	  }
91	
92	  return (
93	    <section data-testid="projects-section">
94	      <h1>Projects</h1>
95	
96	      <form data-testid="project-form" onSubmit={onSubmit}>
97	        <input
98	          data-testid="project-form-name"
99	          placeholder="Project name"
100	          value={name}
101	          onChange={(e) => setName(e.target.value)}
102	        />
103	        <select
104	          data-testid="project-form-client"
105	          value={clientId}
106	          onChange={(e) => setClientId(e.target.value)}
107	        >
108	          <option value="">Select a client</option>
109	          {clients.map((c) => (
110	            <option key={c.id} value={c.id}>
111	              {c.name}
112	            </option>
113	          ))}
114	        </select>
115	        <select
116	          data-testid="project-form-status"
117	          value={status}
118	          onChange={(e) => setStatus(e.target.value)}
119	        >
120	          {PROJECT_STATUSES.map((s) => (
121	            <option key={s} value={s}>
122	              {s}
123	            </option>
124	          ))}
125	        </select>
126	        <button type="submit" data-testid="project-form-submit">
127	          Add project
128	        </button>
129	      </form>
130	
131	      <button
132	        type="button"
133	        data-testid="projects-show-archived"
134	        aria-pressed={showArchived}
135	        onClick={() => setShowArchived((s) => !s)}
136	      >
137	        {showArchived ? 'Hide archived' : 'Show archived'}
138	      </button>
139	
140	      <select
141	        data-testid="project-tag-filter"
142	        value={filterTagId}
143	        onChange={(e) => setFilterTagId(e.target.value)}
144	      >
145	        <option value="">All tags</option>
146	        {tags.map((t) => (
147	          <option key={t.id} value={t.id}>
148	            {t.name}
149	          </option>
150	        ))}
151	      </select>
152	
153	      <select
154	        data-testid="project-status-filter"
155	        value={filterStatus}
156	        onChange={(e) => setFilterStatus(e.target.value)}
157	      >
158	        <option value="">All statuses</option>
159	        {PROJECT_STATUSES.map((s) => (
160	          <option key={s} value={s}>
161	            {s}
162	          </option>
163	        ))}
164	      </select>
165	
166	      {(() => {
167	        const byArchived = showArchived ? projects : projects.filter((p) => !p.archived);
168	        const byTag = filterTagId
169	          ? byArchived.filter((p) => (p.tagIds ?? []).includes(Number(filterTagId)))
170	          : byArchived;
171	        const visible = filterStatus
172	          ? byTag.filter((p) => p.status === filterStatus)
173	          : byTag;
174	        return visible.length === 0 ? (
175	          <p data-testid="projects-empty">No projects yet.</p>
176	        ) : (
177	        <table data-testid="projects-table">
178	          <thead>
179	            <tr>
180	              <th>Name</th>
181	              <th>Client</th>
182	              <th>Status</th>
